package com.supersports.fulfillment;
import java.util.Map;import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository class FulfillmentRepository{private final JdbcTemplate jdbc;FulfillmentRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional Map<String,Object> schedule(UUID order,long fence,String key){if(fence<1)throw new IllegalArgumentException("Fence must be positive");jdbc.update("INSERT INTO fulfillment_fence(order_id,fence) VALUES (?,?) ON CONFLICT(order_id) DO UPDATE SET fence=EXCLUDED.fence WHERE fulfillment_fence.fence < EXCLUDED.fence",order,fence);Long current=jdbc.queryForObject("SELECT fence FROM fulfillment_fence WHERE order_id=? FOR UPDATE",Long.class,order);if(current==null||current!=fence)throw new StaleFenceException();var prior=jdbc.queryForList("SELECT order_id,tracking_id,fence FROM shipment WHERE operation_key=?",key);if(!prior.isEmpty()){if(!order.equals(prior.getFirst().get("order_id")))throw new IllegalStateException("Operation key belongs to another order");return Map.of("orderId",order,"trackingId",prior.getFirst().get("tracking_id"),"state","SCHEDULED","replayed",true);}String tracking="SS-"+order.toString().substring(0,8).toUpperCase();jdbc.update("INSERT INTO shipment(order_id,operation_key,tracking_id,fence,state) VALUES (?,?,?,?,'SCHEDULED')",order,key,tracking,fence);return Map.of("orderId",order,"trackingId",tracking,"state","SCHEDULED","replayed",false);}
 Map<String,Object> status(UUID order){var rows=jdbc.queryForList("SELECT order_id AS \"orderId\",tracking_id AS \"trackingId\",state,created_at AS \"createdAt\" FROM shipment WHERE order_id=?",order);return rows.isEmpty()?Map.of("orderId",order,"state","PENDING"):rows.getFirst();}static class StaleFenceException extends RuntimeException{}}
